import json,shutil,hashlib,html
ROOT=Path(__file__).resolve().parents[1];LIB=ROOT/'Biblioteca de Arte';REL='Personagens Jogaveis/Orc V1';OUT=LIB/REL;OUT.mkdir(parents=True,exist_ok=True)
if (ROOT/'characters/orc-v1/source/equipment-current.json').exists() and json.loads((ROOT/'characters/orc-v1/source/equipment-current.json').read_text(encoding='utf-8'))['revision']!='weapons-v1':
 raise SystemExit('V1 rejected and preserved. Use tools/build-main-orc-rescue-review.py for the current candidate.')
read=lambda p:json.loads(p.read_text(encoding='utf-8-sig'))
files=[]
def copy(source,dest):
 p=OUT/dest;p.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(ROOT/source,p);files.append({'file':dest,'source':source,'sha256':hashlib.sha256(p.read_bytes()).hexdigest()});return dest
concept=copy('characters/orc-v1/concepts/concept-selected.png','Personagem/Conceito.png')
conceptMaster=copy('characters/orc-v1/source/aseprite/concept-selected.aseprite','Personagem/Conceito.aseprite')
idle=read(ROOT/'characters/orc-v1/source/studies/Idle/clip.json')
data=[{'title':'Orc V1 · Idle padrão','state':'Idle','width':128,'height':128,'loop':True,'frames':[{'png':copy(f['png'],f'Personagem/Idle/{i:02d}.png'),'durationMs':f['durationMs']} for i,f in enumerate(idle['frames'])]}]
idleMaster=copy(idle['master'],'Personagem/Idle.aseprite')
rows=[]
for wid in ['recruit-sword','militia-axe']:
 weapon=read(ROOT/f'assets/weapons/{wid}/weapon.json');folder='Armas/'+weapon['name'];sprite=copy(weapon['sprite'],folder+'/'+weapon['name']+'.png');master=copy(weapon['master'],folder+'/'+weapon['name']+'.aseprite')
 copy(f'assets/weapons/{wid}/weapon.json',folder+'/weapon.json')
 sections=[f'<section><h3>Arma separada · uma mão</h3><div class="weapon-stage"><img width="64" height="64" class="weapon" src="{sprite}" alt="{weapon["name"]}"></div><p>{html.escape(weapon["description"])}</p><p><a href="{sprite}">PNG</a> · <a href="{master}">Aseprite</a></p></section>']
 for state,title in [('Walk','Caminhada · loop completo'),('Attack','Golpe · repetido para revisão')]:
  source=f'characters/orc-v1/source/equipment/{wid}/{state}';clip=read(ROOT/source/'clip.json');frames=[]
  for i,f in enumerate(clip['frames']):
   png=copy(f['png'],folder+'/'+state+f'/Quadros/{i:02d}.png');frames.append({'png':png,'durationMs':f['durationMs']})
   for name,item in f['layers'].items():copy(item['png'],folder+'/'+state+f'/Camadas/{name}/{i:02d}.png')
  cm=copy(clip['master'],folder+'/'+state+'/'+state+'.aseprite');sheet=copy(source+'/native-strip.png',folder+'/'+state+'/native-strip.png')
  entry={'title':weapon['name']+' · '+state,'state':state,'width':256,'height':256,'loop':clip['loop'],'frames':frames,'master':cm,'canonicalClip':source+'/clip.json'};i=len(data);data.append(entry)
  local={**clip,'frames':[{'png':f'Quadros/{n:02d}.png','durationMs':f['durationMs'],'sha256':clip['frames'][n]['sha256'],'rightGrip':clip['frames'][n]['rightGrip'],'layers':{name:'Camadas/'+name+f'/{n:02d}.png' for name in clip['frames'][n]['layers']}} for n,f in enumerate(frames)],'master':state+'.aseprite','canonicalClip':source+'/clip.json'}
  (OUT/folder/state/'clip.json').write_text(json.dumps(local,ensure_ascii=False,indent=2),encoding='utf-8')
  sections.append(f'<section><h3>{title}</h3><div class="stage"><canvas id="anim-{i}" width="256" height="256" aria-label="{weapon["name"]} {state}"></canvas></div><p class="frame" id="frame-{i}"></p><p><a href="{cm}">Aseprite com camadas</a> · <a href="{sheet}">Folha completa PNG</a> · <a href="{folder}/{state}/clip.json">Quadros e encaixes</a></p></section>')
 rows.append(f'<article><h2>{weapon["name"]}</h2><div class="weapon-row">'+''.join(sections)+'</div></article>')
STYLE='''*{box-sizing:border-box}body{margin:0;background:#142126;color:#e6ece8;font:15px/1.5 system-ui}main{max-width:1800px;margin:auto;padding:24px}a,h3{color:#dfc18b}p{color:#b8ccc6}h1{font-size:36px}article{border:1px solid #4d666d;border-radius:8px;padding:18px;background:#22353c;margin:20px 0;min-width:0}.hero{display:flex;align-items:center;gap:24px;flex-wrap:wrap}.hero img,.hero canvas{width:256px;height:256px;image-rendering:pixelated}.weapon-row{display:grid;grid-template-columns:210px minmax(0,1fr) minmax(0,1fr);gap:20px}.weapon-row section{min-width:0}.stage{height:536px;overflow:auto;display:flex;justify-content:center;align-items:center;background:repeating-conic-gradient(#283b42 0 25%,#375159 0 50%) 0/20px 20px}.stage canvas{width:512px;height:512px;image-rendering:pixelated;flex-shrink:0}.weapon-stage{height:290px;display:flex;align-items:center;justify-content:center;background:#192a30}.weapon{width:256px;height:256px;image-rendering:pixelated}.toolbar{position:sticky;top:0;display:flex;gap:12px;flex-wrap:wrap;padding:12px;background:#15242a;z-index:2;border-bottom:1px solid #4d666d}button,select{font:inherit;padding:8px;background:#344c54;color:white;border:1px solid #6c868d;border-radius:4px}.frame{font-size:13px}@media(max-width:1250px){.weapon-row{grid-template-columns:1fr}.weapon-stage{justify-content:start}}@media(max-width:600px){main{padding:12px}.stage{height:280px}.stage canvas{width:256px;height:256px}}'''
SCRIPT=r'''const views=data.map(()=>({n:0,time:0,pause:0}));const cache=new Map;let ready=false,playing=true,last=0,speed=1;function asset(p){if(!cache.has(p))cache.set(p,new Promise((ok,no)=>{const im=new Image;im.onload=()=>ok(im);im.onerror=()=>no(Error(p));im.src=p}));return cache.get(p)}async function draw(i){const c=data[i],f=c.frames[views[i].n],im=await asset(f.png),ctx=document.getElementById('anim-'+i).getContext('2d');ctx.imageSmoothingEnabled=false;ctx.clearRect(0,0,c.width,c.height);ctx.drawImage(im,0,0);const note=document.getElementById('frame-'+i);if(note)note.textContent=(views[i].n+1)+'/'+c.frames.length+' quadros · '+f.durationMs+' ms · ciclo '+c.frames.reduce((a,f)=>a+f.durationMs,0)+' ms'}Promise.all(data.flatMap(c=>c.frames.map(f=>asset(f.png)))).then(()=>Promise.all(data.map((_,i)=>draw(i)))).then(()=>{ready=true;document.body.dataset.ready='true'});document.getElementById('play').onclick=()=>{playing=!playing;document.getElementById('play').textContent=playing?'Pausar':'Reproduzir'};document.getElementById('reset').onclick=()=>views.forEach((v,i)=>{v.n=0;v.time=0;v.pause=0;draw(i)});document.getElementById('step').onclick=()=>{playing=false;document.getElementById('play').textContent='Reproduzir';views.forEach((v,i)=>{v.n=(v.n+1)%data[i].frames.length;draw(i)})};document.getElementById('speed').onchange=e=>speed=Number(e.target.value);document.getElementById('zoom').onchange=e=>{const z=Number(e.target.value);document.querySelectorAll('.stage canvas').forEach(c=>c.style.width=c.style.height=(c.width*z)+'px');document.querySelectorAll('.stage').forEach(c=>c.style.height=(256*z+24)+'px')};function tick(t){const dt=last?Math.min(100,t-last)*speed:0;last=t;if(ready&&playing)views.forEach((v,i)=>{const c=data[i];if(v.pause>0){v.pause-=dt;return}v.time+=dt;if(v.time>=c.frames[v.n].durationMs){v.time-=c.frames[v.n].durationMs;v.n=(v.n+1)%c.frames.length;if(v.n===0&&c.state==='Attack')v.pause=350;draw(i)}});requestAnimationFrame(tick)}requestAnimationFrame(tick);'''
page=f'''<!doctype html><html lang="pt-BR"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Orc V1 · espada e machado</title><style>{STYLE}</style><main><h1>Orc V1 · primeiras armas</h1><p>Verde Warcraft selecionado pelo criador como primeiro jogável para futura integração. Armas de uma mão e estudos de golpe/caminhada na vista três quartos.</p><p><a href="../../index.html">Biblioteca de Arte</a> · <a href="../../Orcs Atuais/05 - Infante de Ferro/index.html">Infante original preservado</a> · <a href="LEIA-ME.md">Arquivos e documentação</a></p><div class="toolbar"><button id="play">Pausar</button><button id="reset">Reiniciar</button><button id="step">Avançar quadro</button><label>Velocidade <select id="speed"><option value="1">1×</option><option value="0.5">0,5×</option><option value="0.25">0,25×</option></select></label><label>Zoom equipado <select id="zoom"><option value="1">1× nativo</option><option value="2" selected>2×</option></select></label></div><article class="hero"><section><h3>Orc V1 · conceito</h3><img src="{concept}" alt="Orc V1 Verde Warcraft"></section><section><h3>Idle · padrão fixo 2,2 s</h3><canvas id="anim-0" width="128" height="128"></canvas><p class="frame" id="frame-0"></p></section><section><h2>Seleção preservada</h2><p>Espada e machado são assets independentes.<br>A caminhada armada foi solicitada pelo criador.<br>Armadura e identidade seguem o Orc selecionado.</p><p><a href="{conceptMaster}">Mestre do conceito</a> · <a href="{idleMaster}">Mestre do Idle</a></p></section></article>{''.join(rows)}<p>Prévia local: corpo, arma e dedos têm camadas registradas nos mestres e nos PNGs. O golpe se repete nesta página para revisão; sua ação não é um loop automático no jogo. A integração Unity e as demais vistas ainda são etapas posteriores.</p></main><script>const data={json.dumps(data,ensure_ascii=False)};{SCRIPT}</script></html>'''
(OUT/'index.html').write_text(page,encoding='utf-8')
(OUT/'catalogo.json').write_text(json.dumps({'date':'2026-10-25','character':'orc-v1','players':data,'files':files,'artisticApproval':'PENDING_CREATOR_WEAPONS','unityIntegrated':False},ensure_ascii=False,indent=2),encoding='utf-8')
(OUT/'LEIA-ME.md').write_text('''# Orc V1 — Espada do Recruta e Machado de Milícia

Abra index.html para conceito, Idle padrão e duas armas separadas com caminhada e golpe. Cada arma usa uma mão, a direita anatômica. As duas fotos enviadas pelo criador orientam forma e materiais; o acabamento segue a pixel art do personagem, sem equipamento mágico ou ornamental de alto nível.

Armas/<nome>/ contém PNG e mestre Aseprite independentes em 64×64. Walk/ e Attack/ contêm mestres com camadas, Quadros/, Camadas/, folha completa native-strip.png e clip.json com tempos, encaixes e procedência. Cada composição tem weaponBack, body, weaponFront e handFront. PNGs de composição: 256×256 com o corpo nativo 128×128 deslocado (64,64), PPU100, sem redimensionar a arte. A margem acomoda a arma e seu arco sem cortar pixels. O futuro importador deverá respeitar esse registro, não usar o pivô 128 antigo automaticamente.

Walk: 16 quadros de 80 ms, loop de 1280 ms. Golpe da espada: nove quadros, 1025 ms. Golpe do machado: nove quadros, 1285 ms. As animações de golpe são não repetitivas em gameplay; a página repete para revisão. Evento de contato no clip é marcação visual candidata, não aplica dano no Core.

Fonte canônica: characters/orc-v1/ e assets/weapons/. A origem e SHA256 de cada cópia ficam em catalogo.json. Corpo de ataque herdado de geração PixelLab MCP, adaptação e armas autorais Lua no Aseprite; nada é descrito como desenho manual. Uma geração de espada sem golpe claro foi descartada; o corte corporal mais legível foi reutilizado para as duas armas, com arcos e cadências próprios e limpeza de uma lâmina curta indevida gerada pelo modelo. As caminhadas reaproveitam as 16 poses do Infante e a paleta verde selecionada.

Escopo: estudos de uma vista front_r/south-east, não pacote de quatro direções pronto no runtime. Encaixes e dedos foram revisados na composição, mas a aprovação artística das novas armas/golpes é do criador. Nenhum código ou asset do jogo Unity foi alterado. O Infante original permanece em Orcs Atuais/, previsto para um estágio mais avançado, e as variantes de pele continuam em Estudos Comparativos/.

Atualizar esta página com tools/build-orc-v1-weapons-review.py. Camadas e sprites devem sempre vir dos mestres salvos/exportados no Aseprite.
''',encoding='utf-8')
